51	    <h1>Welcome to Tramed Pharmacy</h1>
52	    <p>Your daily pharmacy management system.</p>
53	
54	    <h2>Today's Summary</h2>
55	    <p>Here is what happened in the pharmacy today:</p>
56	
57	    <ul>
58	      <li>Total invoices: 37</li>
59	      <li>Total revenue: 352,000 RWF</li>
60	      <li>Products low on stock: 4</li>
61	    </ul>
62	
63	    <h2>Today's Sales</h2>
64	
65	    <table>
66	      <thead>
67	        <tr>
68	          <th>Invoice</th>
69	          <th>Product</th>
70	          <th>Quantity</th>
71	          <th>Total (RWF)</th>
72	        </tr>
73	      </thead>
74	      <tbody>
75	        <tr>
76	          <td>101857</td>
77	          <td>FEBRILEX Tablet</td>
78	          <td>8</td>
79	          <td>1,200</td>
80	        </tr>
81	        <tr>
82	          <td>101858</td>
83	          <td>IBUPROFEN 400mg</td>
84	          <td>10</td>
85	          <td>300</td>
86	        </tr>
87	        <tr>
88	          <td>101859</td>
89	          <td>ALCOOL SWAB PAD</td>
90	          <td>4</td>
91	          <td>200</td>
92	        </tr>
93	      </tbody>
94	    </table>
95	
96	    <h2>Total Revenue: <span id="total">0</span> RWF</h2>
97	
98	    <script>
99	
100	      // Step 1: collect the numbers from the last column of the table
101	      let rows = document.querySelectorAll("tbody tr");
102	
103	      // Step 2: add them all up
104	      let total = 0;
105	
106	      rows.forEach(function(row) {
107	        let lastCell = row.querySelectorAll("td")[3];
108	        let amount = parseFloat(lastCell.innerText.replace(",", ""));
109	        total = total + amount;
110	      });
111	      // Step 3: show the result on the page
112	      document.getElementById("total").innerText = total.toLocaleString();
113	
114	    </script>
115	
116	  </body>
