360	// SIMPLE CSV PARSER
361	// ════════════════════════════════════════════════
362	function parseCSV(text) {
363	  const lines = text.trim().split('\n');
364	  const headers = parseLine(lines[0]).map(h => h.trim());
365	  return lines.slice(1).map(line => {
366	    const vals = parseLine(line);
367	    const obj = {};
368	    headers.forEach((h, i) => { obj[h] = (vals[i] || '').trim(); });
369	    return obj;
370	  });
371	}
372	
373	function parseLine(line) {
374	  const result = [];
375	  let cur = '', inQ = false;
376	  for (let i = 0; i < line.length; i++) {
377	    const c = line[i];
378	    if (c === '"') { inQ = !inQ; }
379	    else if (c === ',' && !inQ) { result.push(cur); cur = ''; }
380	    else { cur += c; }
381	  }
382	  result.push(cur);
383	  return result;
384	}
385	
386	function money(n) {
387	  return parseFloat(String(n).replace(/,/g, '')) || 0;
388	}
389	
390	function fmt(n) {
391	  return Math.round(n).toLocaleString('en-US');
392	}
393	
394	function fmtDate(d) {
395	  const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
396	  return `${d.getDate()} ${months[d.getMonth()]} ${d.getFullYear()}`;
397	}
