402	(function() {
403	  const rows = parseCSV(RAW_CSV);
404	
405	  // Exclude insurance copayment lines from revenue (they are just patient shares already counted)
406	  const sales = rows.filter(r => !r['PRODUCT NAME'].includes('INSURANCE COPAYMENT'));
407	
408	  // ── KPIs ──
409	  let totalRevenue = 0, totalCost = 0, totalQty = 0;
410	  sales.forEach(r => {
411	    totalRevenue += money(r['TOTAL']);
412	    totalCost    += money(r['TOTAL COST']);
413	    totalQty     += money(r['QUANTITY']);
414	  });
415	  const grossProfit = totalRevenue - totalCost;
416	  const margin      = totalRevenue > 0 ? (grossProfit / totalRevenue * 100) : 0;
417	  const uniqueInvoices = new Set(sales.map(r => r['INVOICE ID'])).size;
418	
419	  document.getElementById('kpiRevenue').textContent  = fmt(totalRevenue) + ' RWF';
420	  document.getElementById('kpiCost').textContent     = fmt(totalCost)    + ' RWF';
421	  document.getElementById('kpiProfit').textContent   = fmt(grossProfit)  + ' RWF';
422	  document.getElementById('kpiMargin').textContent   = margin.toFixed(1) + '%';
423	  document.getElementById('kpiInvoices').textContent = uniqueInvoices;
424	  document.getElementById('kpiItems').textContent    = sales.length + ' line items';
425	  document.getElementById('txnCount').textContent    = rows.length;
426	
427	  // Report date
428	  const firstDate = rows[0]['DATE'];
429	  const d = new Date(firstDate);
430	  document.getElementById('reportDate').textContent = fmtDate(d);
431	
432	  // ── Top Products ──
433	  const prodMap = {};
434	  sales.forEach(r => {
435	    const name = r['PRODUCT NAME'].trim();
436	    prodMap[name] = (prodMap[name] || 0) + money(r['TOTAL']);
437	  });
438	  const sorted = Object.entries(prodMap).sort((a,b) => b[1]-a[1]).slice(0,10);
439	  const topLabels = sorted.map(([n]) => n.length > 28 ? n.slice(0,28)+'…' : n);
440	  const topValues = sorted.map(([,v]) => v);
441	
442	  new Chart(document.getElementById('chartTopProducts'), {
443	    type: 'bar',
444	    data: {
445	      labels: topLabels,
446	      datasets: [{
447	        label: 'Revenue (RWF)',
448	        data: topValues,
449	        backgroundColor: 'rgba(26,122,74,0.82)',
450	        borderRadius: 4,
451	      }]
452	    },
453	    options: {
454	      indexAxis: 'y',
455	      responsive: true,
456	      maintainAspectRatio: false,
457	      plugins: { legend: { display: false }, tooltip: {
458	        callbacks: { label: ctx => ' ' + fmt(ctx.raw) + ' RWF' }
459	      }},
460	      scales: {
461	        x: { ticks: { callback: v => fmt(v/1000)+'K', font:{size:11} }, grid:{color:'#f0f0f0'} },
462	        y: { ticks: { font:{size:11} } }
463	      }
464	    }
465	  });
466	
467	  // ── Hourly Sales ──
468	  const hourMap = {};
469	  for (let h = 9; h <= 19; h++) hourMap[h] = 0;
470	  sales.forEach(r => {
471	    const hr = parseInt(r['DATE'].split(' ')[1].split(':')[0]);
472	    hourMap[hr] = (hourMap[hr] || 0) + money(r['TOTAL']);
473	  });
474	  const hourKeys   = Object.keys(hourMap).sort((a,b)=>+a-+b);
475	  const hourLabels = hourKeys.map(h => `${h}:00`);
476	  const hourVals   = hourKeys.map(h => hourMap[h]);
477	
478	  new Chart(document.getElementById('chartHourly'), {
479	    type: 'bar',
480	    data: {
481	      labels: hourLabels,
482	      datasets: [{
483	        label: 'Revenue',
484	        data: hourVals,
485	        backgroundColor: hourVals.map(v => v === Math.max(...hourVals) ? '#f0a500' : 'rgba(13,92,54,0.7)'),
486	        borderRadius: 4,
487	      }]
488	    },
489	    options: {
490	      responsive: true,
491	      maintainAspectRatio: false,
492	      plugins: { legend:{display:false}, tooltip:{
493	        callbacks:{ label: ctx => ' ' + fmt(ctx.raw) + ' RWF' }
494	      }},
495	      scales: {
496	        y: { ticks: { callback: v => fmt(v/1000)+'K', font:{size:11} }, grid:{color:'#f0f0f0'} },
497	        x: { ticks:{ font:{size:11} } }
498	      }
499	    }
500	  });
501	
502	  // ── Payment Methods ──
503	  const pmtMap = {};
504	  // group by invoice to avoid double-counting multi-item invoices
505	  const invPmt = {};
506	  const invRev = {};
507	  rows.forEach(r => {
508	    const id  = r['INVOICE ID'];
509	    const pmt = r['CUSTOMER NAME'] || 'CASHNORM';
510	    invPmt[id] = pmt;
511	    invRev[id] = (invRev[id] || 0) + money(r['TOTAL']);
512	  });
513	  Object.entries(invRev).forEach(([id, rev]) => {
514	    const pmt = invPmt[id];
515	    pmtMap[pmt] = (pmtMap[pmt] || 0) + rev;
516	  });
517	
518	  const pmtColors = { CASHNORM:'#1a7a4a', SANLAM:'#0d6efd', RAMA:'#6f42c1', PRIME:'#f0a500' };
519	  const pmtLabels = Object.keys(pmtMap);
520	  const pmtVals   = pmtLabels.map(k => pmtMap[k]);
521	  const pmtBg     = pmtLabels.map(k => pmtColors[k] || '#888');
