529	    options: {
530	      responsive: true,
531	      maintainAspectRatio: false,
532	      plugins: {
533	        legend: { display: false },
534	        tooltip: { callbacks: { label: ctx => ` ${ctx.label}: ${fmt(ctx.raw)} RWF` } }
535	      },
536	      cutout: '62%'
537	    }
