539	
540	  // Custom legend
541	  const legendHTML = pmtLabels.map((k,i) => {
542	    const pct = (pmtVals[i] / pmtVals.reduce((a,b)=>a+b,0) * 100).toFixed(1);
543	    return `<div style="display:flex;align-items:center;gap:6px;margin-bottom:4px;">
544	      <span style="display:inline-block;width:12px;height:12px;border-radius:3px;background:${pmtBg[i]};flex-shrink:0;"></span>
545	      <span style="font-size:.8rem;flex:1;">${k}</span>
546	      <span style="font-size:.78rem;font-weight:600;color:#555;">${pct}%</span>
547	    </div>`;
548	  }).join('');
549	  document.getElementById('paymentLegend').innerHTML = legendHTML;
550	
551	  // ── Stock Alerts ──
552	  const orderNow    = STOCK_DATA.filter(s => s.status === 'Order Now');
553	  const slowMovers  = STOCK_DATA.filter(s => s.status === 'Slow Mover');
554	  const okCount     = STOCK_DATA.filter(s => s.status === 'OK').length;
555	
556	  document.getElementById('stockSummaryBadges').innerHTML =
557	    `<span class="order-now-badge me-1">&#9888; ${orderNow.length} Order Now</span>` +
558	    `<span class="order-now-badge slow-mover-badge me-1">&#8595; ${slowMovers.length} Slow Movers</span>` +
559	    `<span class="order-now-badge ok-badge">&#10003; ${okCount} OK</span>`;
560	
561	  const stockHTML = orderNow.length === 0
562	    ? '<p class="text-muted small mb-0">No urgent stock alerts.</p>'
563	    : orderNow.map(s => `
564	      <div class="stock-item">
565	        <div>
566	          <div class="product-name">${s.name}</div>
567	          <div class="supplier">Supplier: ${s.supplier} &nbsp;|&nbsp; Stockout: ${s.stockoutDate}</div>
568	        </div>
569	        <div class="d-flex align-items-center gap-2">
570	          <span class="qty">QTY: ${s.qty}</span>
571	          <span class="order-now-badge">Order Now</span>
572	        </div>
573	      </div>`).join('');
574	  document.getElementById('stockAlerts').innerHTML = stockHTML;
575	
576	  // ── Transaction Table ──
577	  const pmtBadge = pmt => {
578	    const isCash = pmt === 'CASHNORM';
579	    return `<span class="badge-pmt ${isCash ? 'pmt-cash':'pmt-ins'}">${pmt}</span>`;
580	  };
581	
582	  const tbody = document.getElementById('txnBody');
583	  const rowsHTML = rows.map(r => {
584	    const rev  = money(r['TOTAL']);
585	    const cost = money(r['TOTAL COST']);
586	    const m    = rev > 0 ? ((rev-cost)/rev*100).toFixed(0) : '—';
587	    const time = r['DATE'].split(' ')[1].slice(0,5);
588	    const name = r['PRODUCT NAME'].trim();
589	    const pmt  = (r['CUSTOMER NAME'] || 'CASHNORM').trim();
590	    const mColor = parseFloat(m) < 10 ? 'color:#dc3545;' : parseFloat(m) < 25 ? 'color:#f0a500;' : 'color:#198754;';
591	    return `<tr>
592	      <td>${r['INVOICE ID']}</td>
593	      <td>${time}</td>
594	      <td class="product-cell" title="${name}">${name}</td>
595	      <td style="text-align:right;">${money(r['QUANTITY'])}</td>
596	      <td style="text-align:right;">${fmt(money(r['PRICE']))}</td>
597	      <td style="text-align:right;font-weight:600;">${fmt(rev)}</td>
598	      <td style="text-align:right;color:#6c757d;">${fmt(cost)}</td>
599	      <td style="text-align:right;font-weight:600;${mColor}">${m !== '—' ? m+'%' : '—'}</td>
600	      <td>${pmtBadge(pmt)}</td>
601	    </tr>`;
602	  }).join('');
603	  tbody.innerHTML = rowsHTML;
604	})();
605	</script>
606	</body>
607	</html>
