403	(function() {
404	  const rows = parseCSV(RAW_CSV);
405	
406	  // Exclude insurance copayment lines from revenue (they are just patient shares already counted)
407	  const sales = rows.filter(r => !r['PRODUCT NAME'].includes('INSURANCE COPAYMENT'));
408	
409	  // ── KPIs ──
410	  let totalRevenue = 0, totalCost = 0, totalQty = 0;
411	  sales.forEach(r => {
412	    totalRevenue += money(r['TOTAL']);
413	    totalCost    += money(r['TOTAL COST']);
414	    totalQty     += money(r['QUANTITY']);
415	  });
416	  const grossProfit = totalRevenue - totalCost;
417	  const margin      = totalRevenue > 0 ? (grossProfit / totalRevenue * 100) : 0;
418	  const uniqueInvoices = new Set(sales.map(r => r['INVOICE ID'])).size;
419	
420	  document.getElementById('kpiRevenue').textContent  = fmt(totalRevenue) + ' RWF';
421	  document.getElementById('kpiCost').textContent     = fmt(totalCost)    + ' RWF';
422	  document.getElementById('kpiProfit').textContent   = fmt(grossProfit)  + ' RWF';
423	  document.getElementById('kpiMargin').textContent   = margin.toFixed(1) + '%';
424	  document.getElementById('kpiInvoices').textContent = uniqueInvoices;
425	  document.getElementById('kpiItems').textContent    = sales.length + ' line items';
426	  document.getElementById('txnCount').textContent    = rows.length;
