400	// ════════════════════════════════════════════════
401	// MAIN
402	// ════════════════════════════════════════════════
403	(function() {
404	  const rows = parseCSV(RAW_CSV);
405	
406	  // Exclude insurance copayment lines from revenue (they are just patient shares already counted)
407	  const sales = rows.filter(r => !r['PRODUCT NAME'].includes('INSURANCE COPAYMENT'));
408	
409	  // ── KPIs ──
410	  let totalRevenue = 0, totalCost = 0, totalQty = 0;
411	  sales.forEach(r => {
412	    totalRevenue += money(r['TOTAL']);
413	    totalCost    += money(r['TOTAL COST']);
414	    totalQty     += money(r['QUANTITY']);
415	  });
416	  const grossProfit = totalRevenue - totalCost;
417	  const margin      = totalRevenue > 0 ? (grossProfit / totalRevenue * 100) : 0;
418	  const uniqueInvoices = new Set(sales.map(r => r['INVOICE ID'])).size;
419	
420	  document.getElementById('kpiRevenue').textContent  = fmt(totalRevenue) + ' RWF';
421	  document.getElementById('kpiCost').textContent     = fmt(totalCost)    + ' RWF';
422	  document.getElementById('kpiProfit').textContent   = fmt(grossProfit)  + ' RWF';
423	  document.getElementById('kpiMargin').textContent   = margin.toFixed(1) + '%';
424	  document.getElementById('kpiInvoices').textContent = uniqueInvoices;
425	  document.getElementById('kpiItems').textContent    = sales.length + ' line items';
426	  document.getElementById('txnCount').textContent    = rows.length;
427	
428	  // Report date
429	  const firstDate = rows[0]['DATE'];
430	  const d = new Date(firstDate);
431	  document.getElementById('reportDate').textContent = fmtDate(d);
432	
433	  // ── Top Products ──
434	  const prodMap = {};
435	  sales.forEach(r => {
436	    const name = r['PRODUCT NAME'].trim();
437	    prodMap[name] = (prodMap[name] || 0) + money(r['TOTAL']);
438	  });
439	  const sorted = Object.entries(prodMap).sort((a,b) => b[1]-a[1]).slice(0,10);
440	  const topLabels = sorted.map(([n]) => n.length > 28 ? n.slice(0,28)+'…' : n);
441	  const topValues = sorted.map(([,v]) => v);
442	
443	  new Chart(document.getElementById('chartTopProducts'), {
444	    type: 'bar',
445	    data: {
446	      labels: topLabels,
447	      datasets: [{
448	        label: 'Revenue (RWF)',
449	        data: topValues,
450	        backgroundColor: 'rgba(26,122,74,0.82)',
451	        borderRadius: 4,
452	      }]
453	    },
454	    options: {
455	      indexAxis: 'y',
456	      responsive: true,
457	      maintainAspectRatio: false,
458	      plugins: { legend: { display: false }, tooltip: {
459	        callbacks: { label: ctx => ' ' + fmt(ctx.raw) + ' RWF' }
460	      }},
461	      scales: {
462	        x: { ticks: { callback: v => fmt(v/1000)+'K', font:{size:11} }, grid:{color:'#f0f0f0'} },
463	        y: { ticks: { font:{size:11} } }
464	      }
465	    }
466	  });
467	
468	  // ── Hourly Sales ──
469	  const hourMap = {};
470	  for (let h = 9; h <= 19; h++) hourMap[h] = 0;
471	  sales.forEach(r => {
472	    const hr = parseInt(r['DATE'].split(' ')[1].split(':')[0]);
473	    hourMap[hr] = (hourMap[hr] || 0) + money(r['TOTAL']);
474	  });
475	  const hourKeys   = Object.keys(hourMap).sort((a,b)=>+a-+b);
476	  const hourLabels = hourKeys.map(h => `${h}:00`);
477	  const hourVals   = hourKeys.map(h => hourMap[h]);
478	
479	  new Chart(document.getElementById('chartHourly'), {
480	    type: 'bar',
481	    data: {
482	      labels: hourLabels,
483	      datasets: [{
484	        label: 'Revenue',
485	        data: hourVals,
486	        backgroundColor: hourVals.map(v => v === Math.max(...hourVals) ? '#f0a500' : 'rgba(13,92,54,0.7)'),
487	        borderRadius: 4,
488	      }]
489	    },
490	    options: {
491	      responsive: true,
492	      maintainAspectRatio: false,
493	      plugins: { legend:{display:false}, tooltip:{
494	        callbacks:{ label: ctx => ' ' + fmt(ctx.raw) + ' RWF' }
495	      }},
496	      scales: {
497	        y: { ticks: { callback: v => fmt(v/1000)+'K', font:{size:11} }, grid:{color:'#f0f0f0'} },
498	        x: { ticks:{ font:{size:11} } }
499	      }
500	    }
501	  });
502	
503	  // ── Payment Methods ──
504	  const pmtMap = {};
505	  // group by invoice to avoid double-counting multi-item invoices
506	  const invPmt = {};
507	  const invRev = {};
508	  rows.forEach(r => {
509	    const id  = r['INVOICE ID'];
510	    const pmt = r['CUSTOMER NAME'] || 'CASHNORM';
511	    invPmt[id] = pmt;
512	    invRev[id] = (invRev[id] || 0) + money(r['TOTAL']);
513	  });
514	  Object.entries(invRev).forEach(([id, rev]) => {
515	    const pmt = invPmt[id];
516	    pmtMap[pmt] = (pmtMap[pmt] || 0) + rev;
517	  });
518	
519	  const pmtColors = { CASHNORM:'#1a7a4a', SANLAM:'#0d6efd', RAMA:'#6f42c1', PRIME:'#f0a500' };
520	  const pmtLabels = Object.keys(pmtMap);
521	  const pmtVals   = pmtLabels.map(k => pmtMap[k]);
522	  const pmtBg     = pmtLabels.map(k => pmtColors[k] || '#888');
523	
524	  new Chart(document.getElementById('chartPayment'), {
525	    type: 'doughnut',
526	    data: {
527	      labels: pmtLabels,
528	      datasets: [{ data: pmtVals, backgroundColor: pmtBg, borderWidth: 2 }]
529	    },
530	    options: {
531	      responsive: true,
532	      maintainAspectRatio: false,
533	      plugins: {
534	        legend: { display: false },
535	        tooltip: { callbacks: { label: ctx => ` ${ctx.label}: ${fmt(ctx.raw)} RWF` } }
536	      },
537	      cutout: '62%'
538	    }
539	  });
540	
541	  // Custom legend
542	  const legendHTML = pmtLabels.map((k,i) => {
543	    const pct = (pmtVals[i] / pmtVals.reduce((a,b)=>a+b,0) * 100).toFixed(1);
544	    return `<div style="display:flex;align-items:center;gap:6px;margin-bottom:4px;">
545	      <span style="display:inline-block;width:12px;height:12px;border-radius:3px;background:${pmtBg[i]};flex-shrink:0;"></span>
546	      <span style="font-size:.8rem;flex:1;">${k}</span>
547	      <span style="font-size:.78rem;font-weight:600;color:#555;">${pct}%</span>
548	    </div>`;
549	  }).join('');
550	  document.getElementById('paymentLegend').innerHTML = legendHTML;
551	
552	  // ── Stock Alerts ──
553	  const orderNow    = STOCK_DATA.filter(s => s.status === 'Order Now');
554	  const slowMovers  = STOCK_DATA.filter(s => s.status === 'Slow Mover');
555	  const okCount     = STOCK_DATA.filter(s => s.status === 'OK').length;
556	
557	  document.getElementById('stockSummaryBadges').innerHTML =
558	    `<span class="order-now-badge me-1">&#9888; ${orderNow.length} Order Now</span>` +
559	    `<span class="order-now-badge slow-mover-badge me-1">&#8595; ${slowMovers.length} Slow Movers</span>` +
560	    `<span class="order-now-badge ok-badge">&#10003; ${okCount} OK</span>`;
561	
562	  const stockHTML = orderNow.length === 0
563	    ? '<p class="text-muted small mb-0">No urgent stock alerts.</p>'
564	    : orderNow.map(s => `
565	      <div class="stock-item">
566	        <div>
567	          <div class="product-name">${s.name}</div>
568	          <div class="supplier">Supplier: ${s.supplier} &nbsp;|&nbsp; Stockout: ${s.stockoutDate}</div>
569	        </div>
570	        <div class="d-flex align-items-center gap-2">
571	          <span class="qty">QTY: ${s.qty}</span>
572	          <span class="order-now-badge">Order Now</span>
573	        </div>
574	      </div>`).join('');
575	  document.getElementById('stockAlerts').innerHTML = stockHTML;
576	
577	  // ── Transaction Table ──
578	  const pmtBadge = pmt => {
579	    const isCash = pmt === 'CASHNORM';
580	    return `<span class="badge-pmt ${isCash ? 'pmt-cash':'pmt-ins'}">${pmt}</span>`;
581	  };
582	
583	  const tbody = document.getElementById('txnBody');
584	  const rowsHTML = rows.map(r => {
585	    const rev  = money(r['TOTAL']);
586	    const cost = money(r['TOTAL COST']);
587	    const m    = rev > 0 ? ((rev-cost)/rev*100).toFixed(0) : '—';
588	    const time = r['DATE'].split(' ')[1].slice(0,5);
589	    const name = r['PRODUCT NAME'].trim();
590	    const pmt  = (r['CUSTOMER NAME'] || 'CASHNORM').trim();
591	    const mColor = parseFloat(m) < 10 ? 'color:#dc3545;' : parseFloat(m) < 25 ? 'color:#f0a500;' : 'color:#198754;';
592	    return `<tr>
593	      <td>${r['INVOICE ID']}</td>
594	      <td>${time}</td>
595	      <td class="product-cell" title="${name}">${name}</td>
596	      <td style="text-align:right;">${money(r['QUANTITY'])}</td>
597	      <td style="text-align:right;">${fmt(money(r['PRICE']))}</td>
598	      <td style="text-align:right;font-weight:600;">${fmt(rev)}</td>
599	      <td style="text-align:right;color:#6c757d;">${fmt(cost)}</td>
600	      <td style="text-align:right;font-weight:600;${mColor}">${m !== '—' ? m+'%' : '—'}</td>
601	      <td>${pmtBadge(pmt)}</td>
602	    </tr>`;
603	  }).join('');
604	  tbody.innerHTML = rowsHTML;
605	})();
606	</script>
607	</body>
