  }

  const file = fileInput.files[0]
  const text = await file.text()

  resultDiv.innerHTML = '<div class="alert alert-info">Uploading...</div>'

  const response = await fetch('/api/upload/sales', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
