  })

  const data = await response.json()

  if (response.ok) {
    resultDiv.innerHTML = `<div class="alert alert-success">✓ Imported ${data.rowsImported} rows from <strong>${file.name}</strong></div>`
  } else {
    resultDiv.innerHTML = `<div class="alert alert-danger">Error: ${data.error}</div>`
  }
}
